  let prev = from ?? here;
  let valid = true;
  for (let k = u.pi; k < u.path.length; k++) {
    const t = u.path[k];
    if (!S.rail[t] || (prev !== t && (k > u.pi || S.rail[prev]) && !railNbrs(prev).includes(t))) { valid = false; break; }
    prev = t;
  }
  if (valid) return true;
